mitra=head('Berangkat dari potensi.<br>Bertumbuh lewat kemitraan.','Pendampingan pengembangan ekowisata dan usaha lokal bagi pengelola kawasan, Pokdarwis, perusahaan, pemerintah, produsen, dan agen perjalanan.','ArahWisata untuk mitra','Kemitraan')+f'''<div class="wrap"><div class="wide-photo">{image('galeri-49.jpg','Bentang kawasan yang menghubungkan kebun dan tegakan',lazy=False)}</div></div><section class="section"><div class="wrap grid2"><div><span class="eyebrow">Satu kawasan, satu hubungan pendampingan</span><h2>Dari cerita kawasan<br>menjadi pengalaman<br>yang bernilai.</h2><p class="lead">ArahWisata merancang program, menguatkan keterampilan pengelola, membuka akses pasar, dan membangun kebiasaan pencatatan bersama masyarakat.</p><p class="muted">Hak pengelolaan kawasan, cerita budaya, dan kegiatan ekonomi masyarakat tetap menjadi dasar perjanjian. Ruang lingkup, pembagian peran, dan pembayaran disepakati sejak awal.</p></div><div class="form-panel"><span class="eyebrow">Pendampingan pengembangan kawasan</span><h2>6 bulan</h2><div class="product-price">Rp30.000.000 <small>/ kawasan / siklus</small></div><ul class="check-list"><li>Pemetaan potensi & kebutuhan</li><li>Tiga rancangan program interpretatif</li><li>Standar pelayanan & pelatihan</li><li>Katalog digital & pemasaran terpadu</li><li>Enam laporan pemantauan</li></ul>{btn('#kolaborasi','Diskusikan Kawasan Anda')}<p class="note">Termin layanan: 40% di awal, 30% setelah keluaran pengembangan diterima, dan 30% setelah pendampingan selesai. Rincian final dituangkan dalam perjanjian.</p></div></div></section>
<section class="section divider"><div class="wrap">{section('Yang kita kerjakan bersama.','Keluaran yang jelas, peran yang disepakati, dan evaluasi yang berkelanjutan.','Ruang lingkup layanan')}<div class="deliverables">'''+''.join(f'<article><span class="num">0{i+1}</span><h3>{t}</h3><p>{d}</p></article>' for i,(t,d) in enumerate([('Pemetaan potensi','Membaca sumber daya alam, budaya, agroforestri, kapasitas pengelola, serta kebutuhan pasar.'),('Perancangan program','Menyusun tiga pengalaman interpretatif beserta alur, kapasitas, kebutuhan alat, dan naskah pemanduan.'),('Standar & pelatihan','Menguatkan pelayanan, pengarahan keselamatan, etika pengamatan, dan tata kerja pemandu.'),('Produk & katalog','Membangun identitas asal, cerita produsen, informasi produk, serta materi pemasaran digital.'),('Distribusi & kolaborasi','Menghubungkan program dan produk dengan komunitas, agen, lembaga, pembeli, dan mitra ritel.'),('Monitoring & evaluasi','Mencatat kegiatan dan manfaat, meninjau enam laporan bulanan, serta menyepakati perbaikan.')]))+f'''</div></div></section>
<section class="section dark"><div class="wrap"><span class="eyebrow">Alur pendampingan</span><h2>Langkah yang terarah.<br>Keputusan yang dibangun bersama.</h2><div class="phases"><div class="phase"><small>01 / Mengenali</small><h3>Asesmen & kesepakatan</h3><p>Menyepakati kebutuhan, akses, pembagian peran, dan keluaran layanan.</p></div><div class="phase"><small>02 / Merancang</small><h3>Program & keterampilan</h3><p>Mengembangkan pengalaman, standar pelayanan, dan kapasitas pelaksana.</p></div><div class="phase"><small>03 / Menghubungkan</small><h3>Katalog & pasar</h3><p>Mengemas cerita kawasan dan produk agar dapat ditemukan calon pelanggan.</p></div><div class="phase"><small>04 / Menjaga</small><h3>Tinjauan & perbaikan</h3><p>Pertemuan bulanan, laporan pemantauan, dan evaluasi bersama per triwulan.</p></div></div></div></section>
<section class="section"><div class="wrap grid2"><div><span class="eyebrow">ArahWisata Monitoring Deck</span><h2>Manfaat yang dicatat.<br>Perbaikan yang berlanjut.</h2><p class="lead">Pantau ekonomi, ekologi, sosial budaya, dan tata kelola. Setiap indikator dihubungkan dengan catatan lapangan dan langkah tindak lanjut.</p><div class="actions">{btn('monitoring.html','Buka Ruang Pencatatan')}</div><p class="note">Ruang pencatatan menyimpan data di perangkat Anda dan menyediakan ekspor. Data operasional tidak ditampilkan sebagai capaian publik.</p></div><div class="form-panel"><h3>Empat lensa pemantauan</h3><div class="partner-list" style="border-color:var(--line)"><div style="border-color:var(--line)">Ekonomi <span class="muted">Transaksi & pembayaran mitra</span></div><div style="border-color:var(--line)">Ekologi <span class="muted">Kondisi jalur & sampah</span></div><div style="border-color:var(--line)">Sosial budaya <span class="muted">Keterlibatan & persetujuan</span></div><div style="border-color:var(--line)">Tata kelola <span class="muted">Kapasitas & tindak lanjut</span></div></div><p class="note"><span class="traffic green"></span>Sesuai standar &nbsp; <span class="traffic yellow"></span>Perlu tindak lanjut &nbsp; <span class="traffic red"></span>Hentikan layanan terkait</p></div></div></section>
<section class="section divider" id="kolaborasi"><div class="wrap grid2" style="align-items:start"><div><span class="eyebrow">Mulai percakapan</span><h2>Apa yang ingin<br>Anda tumbuhkan?</h2><p class="lead">Ceritakan kawasan, produk, atau tujuan kolaborasi Anda. Kita mulai dari kebutuhan yang paling berarti bagi masyarakat.</p><div class="info-box"><h4>Untuk siapa?</h4><p>Pengelola kawasan & Pokdarwis · Perusahaan/CSR · Pemerintah & lembaga · Produsen lokal · Agen perjalanan · Ritel.</p><p>Mitra agen dapat mendiskusikan komisi 10% dari harga paket untuk transaksi melalui agen, sesuai kesepakatan kerja sama.</p></div></div><form class="form-panel" id="partner-form"><h3>Mari merancang kolaborasi.</h3><label for="partner-name">Nama lengkap</label><input id="partner-name" name="name" required maxlength="100" autocomplete="name"><label for="partner-org">Organisasi / kawasan / usaha</label><input id="partner-org" name="organization" required maxlength="160" autocomplete="organization"><div class="field-pair"><div><label for="partner-type">Jenis kemitraan</label><select id="partner-type" name="type"><option>Pengelola kawasan / Pokdarwis</option><option>Perusahaan / CSR</option><option>Pemerintah / lembaga</option><option>Produsen lokal</option><option>Agen perjalanan</option><option>Ritel / distribusi</option></select></div><div><label for="partner-email">Email</label><input type="email" id="partner-email" name="email" required autocomplete="email"></div></div><label for="partner-message">Ceritakan kebutuhan Anda</label><textarea id="partner-message" name="message" required maxlength="2500"></textarea><label class="check-label"><input type="checkbox" required>Saya menyetujui penggunaan informasi ini untuk menanggapi permintaan kemitraan sesuai <a href="ketentuan.html#privasi">kebijakan privasi</a>.</label><button class="btn" type="submit">Siapkan Email Kemitraan ↗</button><p class="note">Permintaan dikirim lewat aplikasi email Anda. Periksa lalu kirim email untuk menyampaikan permintaan kepada tim.</p><div class="status" id="partner-result" hidden></div></form></div></section>'''
page('mitra.html','Kemitraan pengembangan kawasan',mitra)

